"""Independent suite for issue #98, generated by qwen/qwen3.8-max via OpenRouter.

Written by a model family that had no part in the service or in the fix, so it
is a genuine second opinion rather than a restatement of our own reasoning.
Provenance and the operator edits are recorded at the bottom of this docstring.

Test suite for GitHub issue #98: PropertyTravelService.calculate_for_property()
must distinguish API failures from genuine "nothing nearby" results.

DEFECT: The current implementation returns True and stores status="not_found"
even when every Google API call was refused (REQUEST_DENIED, OVER_QUERY_LIMIT,
HTTP errors, missing key). This is indistinguishable from a legitimate
"the API answered and there is genuinely nothing nearby" result.

CONTRACT (what the code SHOULD do):
- If all Places calls are refused, calculate_for_property() must return False.
- The stored travel JSON must use a status that is NOT "not_found" for API errors.
  Acceptable error statuses include "error", "api_error", "request_denied", etc.
- If the API answers normally but finds nothing, that IS success: return True,
  store status="not_found".
- Partial failures (Places down, Distance Matrix up) must be surfaced honestly.

Measured, not asserted: against 69566e1 (the commit before the fix) 10 of these
14 tests fail; against the merged fix all 14 pass. The 4 that pass on both are
the controls that a heavy-handed fix would have broken.

Operator edits to the generated module, all mechanical:
  - `source_email_id` added to the fixture (NOT NULL in this schema).
  - `_targets()` helper: the generated assertions walked `travel.items()`, but
    per-target outcomes live under `travel["targets"]`. At the wrong level four
    loops asserted nothing at all and two more failed on both trees.
No assertion, expectation or scenario was changed.
"""

from unittest.mock import MagicMock, patch

import pytest

# --- Project bootstrap (assumed to exist per project conventions) ---
from tests import setup_test_environment

setup_test_environment()

from app import create_app, db  # noqa: E402
from models import Property  # noqa: E402


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

PLACES_URL = "https://maps.googleapis.com/maps/api/place/nearbysearch/json"
DISTANCE_MATRIX_URL = "https://maps.googleapis.com/maps/api/distancematrix/json"

# A minimal preset definition that the service will iterate over.
FAKE_PRESET_DEFS = [
    {
        "key": "school",
        "label": "Nearest school",
        "place_types": ["school"],
    }
]

FAKE_TRAVEL_CONFIG = {
    "presets": {
        "school": {"enabled": True, "mode": "driving"},
    },
    "custom": [],
}


def _targets(travel):
    """Per-target outcomes live under travel["targets"], not at the top level.

    Operator correction, not the model's: the generated assertions walked
    travel.items() directly, where no entry carries a "status" key, so four
    loops never executed a single assertion and two more failed on both the
    fixed and the broken tree. Reading the right level makes them real.
    """
    if not isinstance(travel, dict):
        return {}
    return travel.get("targets") or {}


def _make_response(status_code=200, json_data=None):
    """Build a fake requests.Response-like object."""
    resp = MagicMock()
    resp.status_code = status_code
    resp.json.return_value = json_data or {}
    return resp


def _places_ok_response(results=None):
    """A healthy Places response with optional results."""
    return _make_response(200, {"status": "OK", "results": results or []})


def _places_denied_response():
    """Places returns REQUEST_DENIED (e.g. bad key)."""
    return _make_response(200, {"status": "REQUEST_DENIED", "results": []})


def _places_over_limit_response():
    """Places returns OVER_QUERY_LIMIT."""
    return _make_response(200, {"status": "OVER_QUERY_LIMIT", "results": []})


def _distance_matrix_ok_response():
    """A healthy Distance Matrix response."""
    return _make_response(
        200,
        {
            "status": "OK",
            "rows": [
                {
                    "elements": [
                        {"status": "OK", "duration": {"value": 600, "text": "10 mins"}}
                    ]
                }
            ],
            "destination_addresses": ["123 Main St"],
            "origin_addresses": ["456 Oak Ave"],
        },
    )


