class TestPartialFailure:
    """
    Real-world scenario from the day the bug was found: Places returned
    REQUEST_DENIED (old key in env var) while Distance Matrix answered OK.
    The service must surface the Places failure honestly.
    """

    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_targets_config"
    )
    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_preset_defs"
    )
    @patch("services.property_travel_service.get_cached_enrichment_data")
    @patch("services.property_travel_service.request_with_retries")
    def test_places_denied_distance_matrix_ok_reports_failure(
        self, mock_request, mock_cache, mock_preset_defs, mock_travel_config, app, prop
    ):
        """
        ASSERT: When Places is denied but Distance Matrix would work,
        the method must return False (no destinations were found).
        FAILS TODAY: returns True with "not_found" status.
        """
        mock_cache.return_value = None
        mock_preset_defs.return_value = FAKE_PRESET_DEFS
        mock_travel_config.return_value = FAKE_TRAVEL_CONFIG

        def side_effect(fn, url, **kwargs):
            if "place/nearbysearch" in url:
                return _places_denied_response()
            elif "distancematrix" in url:
                return _distance_matrix_ok_response()
            return _make_response(404, {})

        mock_request.side_effect = side_effect

        from services.property_travel_service import PropertyTravelService

        svc = PropertyTravelService(google_places_key="FAKE_KEY")
        svc.location_service = MagicMock()
        svc.location_service.ensure_coordinates.return_value = True

        result = svc.calculate_for_property(prop, commit=True)

        # Places failed → no destinations found → no travel times computed.
        # The method must not pretend this was a success.
        assert result is False, (
            "calculate_for_property() returned True even though Places was "
            "REQUEST_DENIED. Distance Matrix being healthy doesn't help if "
            "we never found any destinations. Must return False."
        )

    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_targets_config"
    )
    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_preset_defs"
    )
    @patch("services.property_travel_service.get_cached_enrichment_data")
    @patch("services.property_travel_service.request_with_retries")
    def test_partial_failure_travel_json_has_error_status(
        self, mock_request, mock_cache, mock_preset_defs, mock_travel_config, app, prop
    ):
        """
        ASSERT: In the partial-failure case, the travel JSON must record
        an error status for the Places-dependent targets, not "not_found".
        FAILS TODAY: stores "not_found".
        """
        mock_cache.return_value = None
        mock_preset_defs.return_value = FAKE_PRESET_DEFS
        mock_travel_config.return_value = FAKE_TRAVEL_CONFIG

        def side_effect(fn, url, **kwargs):
            if "place/nearbysearch" in url:
                return _places_denied_response()
            elif "distancematrix" in url:
                return _distance_matrix_ok_response()
            return _make_response(404, {})

        mock_request.side_effect = side_effect

        from services.property_travel_service import PropertyTravelService

        svc = PropertyTravelService(google_places_key="FAKE_KEY")
        svc.location_service = MagicMock()
        svc.location_service.ensure_coordinates.return_value = True

        svc.calculate_for_property(prop, commit=True)
        db.session.refresh(prop)

        travel = prop.travel
        if travel and isinstance(travel, dict):
            for key, val in _targets(travel).items():
                if isinstance(val, dict) and "status" in val:
                    assert val["status"] != "not_found", (
                        f"Target '{key}' shows 'not_found' but Places was "
                        f"REQUEST_DENIED. Must use a distinct error status."
                    )


# ---------------------------------------------------------------------------
# Test 3: Genuine "nothing nearby" — this IS success (control test)
# ---------------------------------------------------------------------------


class TestGenuineNothingNearby:
    """
    CONTROL: When the API answers normally (status=OK) but returns an empty
    results list, that is a legitimate "nothing nearby". The method MUST
    return True and store "not_found". An over-eager fix that makes ALL
    empty results look like errors would break this.
    """

    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_targets_config"
    )
    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_preset_defs"
    )
    @patch("services.property_travel_service.get_cached_enrichment_data")
    @patch("services.property_travel_service.request_with_retries")
    def test_genuine_empty_results_is_success(
        self, mock_request, mock_cache, mock_preset_defs, mock_travel_config, app, prop
    ):
        """
        ASSERT: API returns OK with empty results → method returns True.
        This must PASS both before and after the fix.
        """
        mock_cache.return_value = None
        mock_preset_defs.return_value = FAKE_PRESET_DEFS
        mock_travel_config.return_value = FAKE_TRAVEL_CONFIG

        # Places answers normally but finds nothing
        mock_request.return_value = _places_ok_response(results=[])

        from services.property_travel_service import PropertyTravelService

        svc = PropertyTravelService(google_places_key="FAKE_KEY")
        svc.location_service = MagicMock()
        svc.location_service.ensure_coordinates.return_value = True

        result = svc.calculate_for_property(prop, commit=True)

        # This IS a successful enrichment run — the API worked, there's just
        # nothing nearby. Must return True.
        assert result is True, (
            "calculate_for_property() returned False even though the API "
            "answered OK with empty results. A genuine 'nothing nearby' is "
            "a valid, successful result."
        )

    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_targets_config"
    )
    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_preset_defs"
    )
    @patch("services.property_travel_service.get_cached_enrichment_data")
    @patch("services.property_travel_service.request_with_retries")
    def test_genuine_empty_results_stores_not_found(
        self, mock_request, mock_cache, mock_preset_defs, mock_travel_config, app, prop
    ):
        """
        ASSERT: Genuine empty results → travel JSON has status="not_found".
        This must PASS both before and after the fix.
        """
        mock_cache.return_value = None
        mock_preset_defs.return_value = FAKE_PRESET_DEFS
        mock_travel_config.return_value = FAKE_TRAVEL_CONFIG

        mock_request.return_value = _places_ok_response(results=[])

        from services.property_travel_service import PropertyTravelService

        svc = PropertyTravelService(google_places_key="FAKE_KEY")
        svc.location_service = MagicMock()
        svc.location_service.ensure_coordinates.return_value = True

        svc.calculate_for_property(prop, commit=True)
        db.session.refresh(prop)

        travel = prop.travel
        assert travel is not None, "Travel JSON should be written on success."

        # At least one target should have status "not_found"
        found_not_found = False
        if isinstance(travel, dict):
            for key, val in _targets(travel).items():
                if isinstance(val, dict) and val.get("status") == "not_found":
                    found_not_found = True
                    break

        assert found_not_found, (
            "When the API genuinely finds nothing, the travel JSON should "
            "contain status='not_found'. This is the legitimate use of that status."
        )


